theory = (
 H("A", "Animals and plants", "Động vật và thực vật")
 + P("Three short nature texts: about elephants, a plant called the cherry laurel, and the South African secretary bird.", "Ba đoạn văn ngắn về thiên nhiên: về loài voi, cây nguyệt quế anh đào (cherry laurel) và chim thư ký Nam Phi.")
 + T([
    ("<b>feed on</b>", "Elephants live by eating plants.", "Voi sống nhờ ăn thực vật."),
    ("<b>pull down</b> / <b>break off</b> / <b>pull up</b>", "Elephants knock trees over to reach the leaves, snap branches off and tear plants out of the ground, making clearings where new plants grow.", "Voi kéo đổ cây để ăn lá, bẻ gãy cành và nhổ bật cây lên, tạo ra những khoảng trống để cây mới mọc."),
    ("<b>die out</b>", "Because of this destructive feeding, some plants are close to disappearing completely.", "Vì kiểu ăn phá hoại đó, một số loài cây có nguy cơ tuyệt chủng."),
    ("<b>dry out</b>", "The cherry laurel needs soil that is always moist – it must not become dry.", "Cây nguyệt quế anh đào cần đất luôn ẩm – không được để đất khô."),
    ("<b>cut down</b> / <b>send out</b> / <b>offshoot</b>", "Even if the tree is cut to the ground, it still grows new branches from the root and new small plants from the base of the stem.", "Dù cây bị chặt sát gốc, nó vẫn mọc nhánh mới từ rễ và chồi non từ chân thân."),
    ("<b>dig up</b> / <b>come out</b>", "It is very difficult to remove from the ground; its small flowers appear in late spring.", "Rất khó đào bỏ cây này; những bông hoa nhỏ của nó nở vào cuối xuân."),
    ("<b>prey on</b> / <b>pick up</b>", "The secretary bird catches and eats insects, snakes, tortoises and rats; it lifts small prey with its bill and swallows them.", "Chim thư ký săn côn trùng, rắn, rùa và chuột; nó dùng mỏ gắp con mồi nhỏ rồi nuốt."),
    ("<b>flush out</b>", "It stamps on the ground to force prey out of hiding.", "Nó dậm chân xuống đất để buộc con mồi chui ra khỏi chỗ nấp."),
 ])
 + H("B", "Water and sky", "Nước và bầu trời")
 + T([
    ("<b>dry up</b>", "Water in a river disappears – the river now in flood was completely dry six months ago.", "Nước sông cạn hết – con sông giờ đang lũ, sáu tháng trước lại khô cạn."),
    ("<b>freeze over</b>", "The sea in the far north is covered with ice for months each year (see the demo card, Unit 2).", "Biển ở vùng cực bắc đóng băng nhiều tháng mỗi năm (xem thẻ demo, bài 2)."),
    ("<b>go out</b> / <b>come in</b>", "The tide moves away from the beach, so you can look for shellfish, but it moves back in quickly.", "Thủy triều rút xa bờ nên có thể đi bắt sò ốc, nhưng triều lên lại rất nhanh."),
    ("<b>come out</b>", "The stars appear at night, which is spectacular.", "Ban đêm sao xuất hiện, trông rất đẹp."),
    ("<b>go in</b>", "The sun is now hidden behind a cloud and it is getting cold.", "Mặt trời đã khuất sau mây và trời trở lạnh."),
    ("<b>overcast</b>", "(adjective) The sky is grey and cloudy, so the speaker won’t go to the beach.", "(tính từ) Trời xám và nhiều mây nên người nói không đi biển."),
    ("<b>wash away</b>", "A very high tide carried away an old boat left on the beach.", "Một đợt triều cao bất thường cuốn trôi chiếc thuyền cũ bị bỏ trên bãi."),
    ("<b>eat away at</b>", "The sea is slowly destroying the cliff, so houses near the edge are in danger.", "Biển đang dần xâm thực vách đá, nên những ngôi nhà gần mép đang gặp nguy."),
 ])
 + NOTE("<b>Exercise 47.4</b> adds verbs about animals: grey squirrels <b>moved in</b>, <b>chased</b> the native red squirrels <b>out</b> and <b>took over</b> their territory; many animals <b>bring up</b> their young like human parents, <b>watching over</b> them until they are mature, while others leave their young to <b>fend for</b> themselves soon after birth.",
        "<b>Bài 47.4</b> bổ sung động từ về động vật: sóc xám <b>đến sinh sống</b>, <b>đuổi</b> sóc đỏ bản địa <b>đi</b> rồi <b>chiếm</b> lãnh thổ của chúng; nhiều loài <b>nuôi dạy</b> con giống cha mẹ loài người, <b>trông chừng</b> chúng đến khi trưởng thành, còn loài khác để con <b>tự xoay xở</b> ngay sau khi sinh.")
)
